import{_ as n,a0 as d,w as r,s as p,I as e,x as s,a1 as t,A as l,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"為初學者準備的 MariaDB 管理命令 | LCTT x X-CMD","titleTemplate":false,"description":"為初學者準備的 MariaDB 管理命令 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為初學者準備的 MariaDB 管理命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為初學者準備的 MariaDB 管理命令 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171202 MariaDB administration commands for beginners","title":"為初學者準備的 MariaDB 管理命令","tag":"201802","desc":""},"relativePath":"201802/20171202 MariaDB administration commands for beginners.md","filePath":"[post].md"}'),h={name:"201802/20171202 MariaDB administration commands for beginners.md"};function g(b,a,k,c,u,m){const i=d("Link");return r(),p("div",null,[a[19]||(a[19]=e("h1",{id:"為初學者準備的-mariadb-管理命令",tabindex:"-1"},[s("為初學者準備的 MariaDB 管理命令 "),e("a",{class:"header-anchor",href:"#為初學者準備的-mariadb-管理命令","aria-label":"Permalink to “為初學者準備的 MariaDB 管理命令”"},"​")],-1)),e("p",null,[a[1]||(a[1]=s("之前我們學過了",-1)),t(i,{href:"http://linuxtechlab.com/installing-configuring-mariadb-rhelcentos/"},{default:l(()=>[...a[0]||(a[0]=[s("在 Centos/RHEL 7 上安裝 MariaDB 服務器並保證其安全",-1)])]),_:1}),a[2]||(a[2]=s("，使之成為了 RHEL/CentOS 7 的默認資料庫。現在我們再來看看一些有用的 MariaDB 管理命令。這些都是使用 MariaDB 最基礎的命令，而且它們對 MySQL 也同樣適合，因為 Mariadb 就是 MySQL 的一個分支而已。",-1))]),e("p",null,[e("strong",null,[a[4]||(a[4]=s("(推薦閲讀：",-1)),t(i,{href:"http://linuxtechlab.com/mongodb-installation-configuration-rhelcentos/"},{default:l(()=>[...a[3]||(a[3]=[s("在 RHEL/CentOS 上安裝並配置 MongoDB",-1)])]),_:1}),a[5]||(a[5]=s(")",-1))])]),a[20]||(a[20]=o(`<h3 id="mariadb-管理命令" tabindex="-1">MariaDB 管理命令 <a class="header-anchor" href="#mariadb-管理命令" aria-label="Permalink to “MariaDB 管理命令”">​</a></h3><h4 id="_1、查看-mariadb-安裝的版本" tabindex="-1">1、查看 MariaDB 安裝的版本 <a class="header-anchor" href="#_1、查看-mariadb-安裝的版本" aria-label="Permalink to “1、查看 MariaDB 安裝的版本”">​</a></h4><p>要查看所安裝資料庫的當前版本，在終端中輸入下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -version</span></span></code></pre></div><p>該命令會告訴你資料庫的當前版本。此外你也可以運行下面命令來查看版本的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqladmin -u root -p version</span></span></code></pre></div><h4 id="_2、登錄-mariadb" tabindex="-1">2、登錄 MariaDB <a class="header-anchor" href="#_2、登錄-mariadb" aria-label="Permalink to “2、登錄 MariaDB”">​</a></h4><p>要登錄 MariaDB 服務器，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><p>然後輸入密碼登錄。</p><h4 id="_3、列出所有的資料庫" tabindex="-1">3、列出所有的資料庫 <a class="header-anchor" href="#_3、列出所有的資料庫" aria-label="Permalink to “3、列出所有的資料庫”">​</a></h4><p>要列出 MariaDB 當前擁有的所有資料庫，在你登錄到 MariaDB 中後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; show databases;</span></span></code></pre></div><p>（LCTT 譯註：<code>$</code> 這裏代表 shell 的提示符，<code>&gt;</code> 這裏代表 MariaDB shell 的提示符。）</p><h4 id="_4、創建新資料庫" tabindex="-1">4、創建新資料庫 <a class="header-anchor" href="#_4、創建新資料庫" aria-label="Permalink to “4、創建新資料庫”">​</a></h4><p>在 MariaDB 中創建新資料庫，登錄 MariaDB 後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; create database dan;</span></span></code></pre></div><p>若想直接在終端創建資料庫，則運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqladmin -u user -p create dan</span></span></code></pre></div><p>這裏，<code>dan</code> 就是新資料庫的名稱。</p><h4 id="_5、刪除資料庫" tabindex="-1">5、刪除資料庫 <a class="header-anchor" href="#_5、刪除資料庫" aria-label="Permalink to “5、刪除資料庫”">​</a></h4><p>要刪除資料庫，在已登錄的 MariaDB 會話中運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; drop database dan;</span></span></code></pre></div><p>此外你也可以運行，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqladmin -u root -p drop dan</span></span></code></pre></div><p><strong>注意：</strong> 若在運行 <code>mysqladmin</code> 命令時提示 “access denied” 錯誤，這應該是由於我們沒有給 root 授權。要對 root 授權，請參照第 7 點方法，只是要將用户改成 root。</p><h4 id="_6、創建新用户" tabindex="-1">6、創建新用户 <a class="header-anchor" href="#_6、創建新用户" aria-label="Permalink to “6、創建新用户”">​</a></h4><p>為資料庫創建新用户，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE USER &#39;dan&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;password&#39;;</span></span></code></pre></div><h4 id="_7、授權用户訪問某個資料庫" tabindex="-1">7、授權用户訪問某個資料庫 <a class="header-anchor" href="#_7、授權用户訪問某個資料庫" aria-label="Permalink to “7、授權用户訪問某個資料庫”">​</a></h4><p>授權用户訪問某個資料庫，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; GRANT ALL PRIVILEGES ON test.* to &#39;dan&#39;@&#39;localhost&#39;;</span></span></code></pre></div><p>這會賦予用户 <code>dan</code> 對名為 <code>test</code> 的資料庫完全操作的權限。我們也可以限定為用户只賦予 <code>SELECT</code>、<code>INSERT</code>、<code>DELETE</code> 權限。</p><p>要賦予訪問所有資料庫的權限，將 <code>test</code> 替換成 <code>*</code> 。像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; GRANT ALL PRIVILEGES ON *.* to &#39;dan&#39;@&#39;localhost&#39;;</span></span></code></pre></div><h4 id="_8、備份-導出資料庫" tabindex="-1">8、備份/導出資料庫 <a class="header-anchor" href="#_8、備份-導出資料庫" aria-label="Permalink to “8、備份/導出資料庫”">​</a></h4><p>要創建單個數據庫的備份，在終端窗口中運行下列命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p database_name&gt;db_backup.sql</span></span></code></pre></div><p>若要一次性創建多個數據庫的備份則運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p --databases db1 db2 &gt; db12_backup.sql</span></span></code></pre></div><p>要一次性導出多個數據庫，則運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p --all-databases &gt; all_dbs.sql</span></span></code></pre></div><h4 id="_9、從備份中恢復資料庫" tabindex="-1">9、從備份中恢復資料庫 <a class="header-anchor" href="#_9、從備份中恢復資料庫" aria-label="Permalink to “9、從備份中恢復資料庫”">​</a></h4><p>要從備份中恢復資料庫，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p database_name &lt; db_backup.sql</span></span></code></pre></div><p>但這條命令成功的前提是預先沒有存在同名的資料庫。如果想要恢復資料庫數據到已經存在的資料庫中，則需要用到 <code>mysqlimport</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqlimport -u root -p database_name &lt; db_backup.sql</span></span></code></pre></div><h4 id="_10、更改-mariadb-用户的密碼" tabindex="-1">10、更改 mariadb 用户的密碼 <a class="header-anchor" href="#_10、更改-mariadb-用户的密碼" aria-label="Permalink to “10、更改 mariadb 用户的密碼”">​</a></h4><p>本例中我們會修改 <code>root</code> 的密碼，但修改其他用户的密碼也是一樣的過程。</p><p>登錄 mariadb 並切換到 &#39;mysql&#39; 資料庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>&gt; use mysql;</span></span></code></pre></div><p>然後運行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; update user set password=PASSWORD(&#39;your_new_password_here&#39;) where User=&#39;root&#39;;</span></span></code></pre></div><p>下一步，重新加載權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; flush privileges;</span></span></code></pre></div><p>然後退出會話。</p><p>我們的教程至此就結束了，在本教程中我們學習了一些有用的 MariaDB 管理命令。歡迎您的留言。</p><hr>`,58)),e("p",null,[a[7]||(a[7]=s("via: ",-1)),t(i,{href:"http://linuxtechlab.com/mariadb-administration-commands-beginners/"},{default:l(()=>[...a[6]||(a[6]=[s("http://linuxtechlab.com/mariadb-administration-commands-beginners/",-1)])]),_:1})]),e("p",null,[a[11]||(a[11]=s("作者：",-1)),t(i,{href:"http://linuxtechlab.com/author/shsuain/"},{default:l(()=>[...a[8]||(a[8]=[s("Shusain",-1)])]),_:1}),a[12]||(a[12]=s(" 譯者：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[13]||(a[13]=s(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...a[10]||(a[10]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[16]||(a[16]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[14]||(a[14]=[s("LCTT",-1)])]),_:1}),a[17]||(a[17]=s(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...a[15]||(a[15]=[s("Linux中國",-1)])]),_:1}),a[18]||(a[18]=s(" 榮譽推出",-1))])])}const x=n(h,[["render",g]]);export{C as __pageData,x as default};
